	(179, 34, '2025-06-01', '운동시간', '아침 식사 잘 하심, 낮잠 주무심, 오후 산책 다녀오심.', '2025-07-07 12:14:27', '2025-07-25 11:06:02'),
	(180, 34, '2025-06-01', '복약여부', '식사 정상, 수면 양호, 외출 없음.', '2025-07-07 12:14:27', '2025-07-25 11:06:04'),
	(181, 34, '2025-06-02', '건강상태', '모든 식사 잘 하심, 밤에 깊이 주무심, 외출은 없었음.', '2025-07-07 12:14:27', '2025-07-25 11:06:07'),
	(182, 34, '2025-06-02', '세탁횟수', '식사 보통, 수면 보통, 마트 외출.', '2025-07-07 12:14:27', '2025-07-25 11:06:09'),
	(183, 34, '2025-06-03', '세탁횟수', '아침 식사 소량, 약 복용 거부. 종일 무기력해 보임. 밤에 자주 깨셨음.', '2025-07-07 12:14:27', '2025-07-25 11:06:12'),
	(184, 34, '2025-06-03', '복약여부', '식사 양호, 낮잠 주무심, 외출 없음.', '2025-07-07 12:14:27', '2025-07-25 11:06:14'),
	(185, 34, '2025-06-04', '복약여부', '식욕 없어 식사량 매우 적음. 외출 거부. 밤에 불면 증세.', '2025-07-07 12:14:27', '2025-07-25 11:06:16'),
	(186, 34, '2025-06-04', '건강상태', '식사 좋음, 수면 좋음, 병원 방문.', '2025-07-07 12:14:27', '2025-07-25 11:06:18'),
	(187, 34, '2025-06-05', '활동수준', '식사량 회복. 밤에 숙면 취하심. 가벼운 실내 스트레칭.', '2025-07-07 12:14:27', '2025-07-25 11:06:21'),
	(188, 34, '2025-06-05', '세탁횟수', '식사 양호, 수면 양호, 외출 없음.', '2025-07-07 12:14:27', '2025-07-25 11:06:23'),
	(189, 34, '2025-06-06', '운동시간', '약 복용에 어려움. 식사는 보통. 밤에 깊은 잠은 아닌 듯.', '2025-07-07 12:14:27', '2025-07-25 11:06:26'),
	(190, 34, '2025-06-06', '건강상태', '세 끼 식사 잘 하심, 밤에 잘 주무심, 집 안에서만 활동.', '2025-07-07 12:14:27', '2025-07-25 11:06:28'),
	(191, 34, '2025-06-07', '복약여부', '식사 거부, 물만 드심. 몸이 좋지 않다고 호소. 낮잠 없이 불안정한 수면.', '2025-07-07 12:14:27', '2025-07-25 11:05:52'),
	(192, 34, '2025-06-07', '건강상태', '식사 잘 하심, 밤에 숙면 취하심, 오후에 산책.', '2025-07-07 12:14:27', '2025-07-25 11:05:55'),
	(193, 34, '2025-06-08', '복약여부', '아침 식사 미음 소량. 병원 다녀온 후 계속 주무심. 건강이 염려됨.', '2025-07-07 12:14:27', '2025-07-25 11:05:46'),
	(194, 34, '2025-06-08', '복약여부', '식사 좋음, 밤에 편안하게 주무심, 외출 없음.', '2025-07-07 12:14:27', '2025-07-25 11:05:48'),
	(195, 34, '2025-06-09', '건강상태', '식사량 조금 늘어남. 주로 침대에 누워 휴식. 비교적 편안하게 주무심.', '2025-07-07 12:14:27', '2025-07-25 11:05:41'),
	(196, 34, '2025-06-09', '세탁횟수', '식사 양호, 수면 양호, 외출 없음.', '2025-07-07 12:14:27', '2025-07-25 11:05:43'),
	(197, 34, '2025-06-10', '운동시간', '식사량 정상화, 약 복용 완료. 밤에 숙면 취하심. 가벼운 거실 활동.', '2025-07-07 12:14:27', '2025-07-25 11:05:35'),
	(198, 34, '2025-06-10', '식사횟수', '식사 좋음, 수면 좋음, 병원 다녀오심.', '2025-07-07 12:14:27', '2025-07-25 11:05:37'),
	(199, 34, '2025-06-11', '운동시간', '모든 식사 잘 하심, 밤에 편안하게 주무심. 퍼즐 맞추기.', '2025-07-07 12:14:27', '2025-07-25 11:05:30'),
	(200, 34, '2025-06-11', '운동시간', '식사 양호, 수면 양호, 외출 없음.', '2025-07-07 12:14:27', '2025-07-25 11:05:32'),
	(201, 34, '2025-06-12', '활동수준', '식사 거부, 속이 안 좋다고 하심. 얼굴 창백, 식은땀. 불안정한 수면, 자주 깨심.', '2025-07-07 12:14:27', '2025-07-25 11:05:25'),
	(202, 34, '2025-06-12', '운동시간', '식사 보통, 낮잠 주무심, 외출 없음.', '2025-07-07 12:14:27', '2025-07-25 11:05:27'),
	(203, 34, '2025-06-13', '건강상태', '식사량 극히 적음, 복통 호소. 응급실 방문 후 입원. 병원에서 수액 맞으며 잠드심.', '2025-07-07 12:14:27', '2025-07-25 11:05:22'),
	(204, 34, '2025-06-13', '활동수준', '식사 양호, 수면 양호, 산책 다녀오심.', '2025-07-07 12:14:27', '2025-07-25 11:05:20'),
	(205, 34, '2025-06-14', '운동시간', '미음만 소량 드심. 기력 없음. 기침이 심하고 미열. 기침으로 자주 깨셨음.', '2025-07-07 12:14:27', '2025-07-25 11:05:16'),
	(206, 34, '2025-06-14', '활동수준', '식사 좋음, 밤에 잘 주무심, 외출 없음.', '2025-07-07 12:14:27', '2025-07-25 11:05:18'),
	(207, 34, '2025-06-15', '건강상태', '식사량 회복. 밤에 잘 주무심. 안정 취하며 휴식.', '2025-07-07 12:14:27', '2025-07-25 11:05:10'),
	(208, 34, '2025-06-15', '세탁횟수', '식사 양호, 수면 양호, 외출 없음.', '2025-07-07 12:14:27', '2025-07-25 11:05:12'),
	(209, 34, '2025-06-16', '복약여부', '식사 잘 하심. 밤에 숙면 취하심. 은행 업무로 외출.', '2025-07-07 12:14:27', '2025-07-25 11:05:05'),
	(210, 34, '2025-06-16', '운동시간', '세 끼 식사 잘 하심, 밤에 잘 주무심, 외출 없음.', '2025-07-07 12:14:27', '2025-07-25 11:05:07'),
	(211, 34, '2025-06-17', '식사횟수', '식사 잘 하심. 잘 주무심. 특별한 활동 없는 평온한 하루.', '2025-07-07 12:14:27', '2025-07-25 11:04:58'),
	(212, 34, '2025-06-17', '활동수준', '식사 양호, 수면 양호, 외출 없음.', '2025-07-07 12:14:27', '2025-07-25 11:05:02'),
	(213, 34, '2025-06-18', '활동수준', '아침 식사량 적었음. 오후에 다리 통증 호소, 파스 부착. 통증으로 인해 잠을 설침.', '2025-07-07 12:14:27', '2025-07-25 11:04:51'),
	(214, 34, '2025-06-18', '운동시간', '식사 좋음, 밤에 편안하게 주무심, 외출 없음.', '2025-07-07 12:14:27', '2025-07-25 11:04:54'),
	(215, 34, '2025-06-19', '활동수준', '식사 잘 하심. 밤에 숙면 취하심. 오후 산책 다녀오심.', '2025-07-07 12:14:27', '2025-07-25 11:04:45'),
	(216, 34, '2025-06-19', '복약여부', '식사 양호, 수면 양호, 외출 없음.', '2025-07-07 12:14:27', '2025-07-25 11:04:48'),
	(217, 34, '2025-06-20', '건강상태', '약 복용 완료, 식사 잘 하심. 늦게까지 이야기하다 주무심. 자녀분 방문.', '2025-07-07 12:14:27', '2025-07-25 11:04:39'),
	(218, 34, '2025-06-20', '세탁횟수', '식사 좋음, 밤에 잘 주무심, 외출 없음.', '2025-07-07 12:14:27', '2025-07-25 11:04:42'),
	(219, 34, '2025-06-21', '복약여부', '식사 잘 하심. 잘 주무심. 독서하며 시간 보내심.', '2025-07-07 12:14:27', '2025-07-25 11:04:34'),
	(220, 34, '2025-06-21', '세탁횟수', '식사 양호, 수면 양호, 친구분 방문.', '2025-07-07 12:14:27', '2025-07-25 11:04:36'),
	(221, 34, '2025-06-22', '복약여부', '아침 식사 거부, 속이 안 좋다고 하심. 하루 종일 무기력. 밤에 뒤척임.', '2025-07-07 12:14:27', '2025-07-25 11:04:28'),
	(222, 34, '2025-06-22', '건강상태', '식사 좋음, 밤에 편안하게 주무심, 외출 없음.', '2025-07-07 12:14:27', '2025-07-25 11:04:31'),
	(223, 34, '2025-06-23', '운동시간', '식사량 약간 회복. 낮잠 주무심. 오후에 가벼운 산책.', '2025-07-07 12:14:27', '2025-07-25 11:04:22'),
