-- 테이블 health_care.seniors 구조 내보내기
CREATE TABLE IF NOT EXISTS `seniors` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '노인 고유 ID',
  `guardian_id` int(11) NOT NULL COMMENT 'users 테이블 참조',
  `senior_name` varchar(30) NOT NULL,
  `birth_date` date NOT NULL COMMENT '생년월일',
  `gender` char(1) DEFAULT NULL COMMENT '성별 (M/F)',
  `phone` varchar(20) DEFAULT NULL COMMENT '노인 본인 연락처',
  `address` varchar(255) DEFAULT NULL COMMENT '주소',
  `emergency_contact` varchar(20) DEFAULT NULL COMMENT '비상연락처',
  `chronic_diseases` text DEFAULT NULL COMMENT '주요 지병',
  `medications` text DEFAULT NULL COMMENT '복용중인 주요 약물',
  `notes` text DEFAULT NULL COMMENT '특이사항',
  `daily_activities` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '활동기록',
  `is_active` tinyint(1) NOT NULL DEFAULT 1 COMMENT '활성 상태',
  `created_at` datetime DEFAULT current_timestamp() COMMENT '등록일',
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp() COMMENT '수정일',
  PRIMARY KEY (`id`),
  KEY `idx_birth_date` (`birth_date`),
  KEY `idx_guardian_id` (`guardian_id`),
  KEY `idx_senior_name` (`senior_name`),
  KEY `idx_is_active` (`is_active`),
  CONSTRAINT `FK_seniors_guardians` FOREIGN KEY (`guardian_id`) REFERENCES `guardians` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=55 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='독거노인 기본정보';

