-- 테이블 health_care.user_setting 구조 내보내기
CREATE TABLE IF NOT EXISTS `user_setting` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `guardian_id` int(11) NOT NULL DEFAULT 0,
  `category` varchar(255) NOT NULL,
  `sub_category` varchar(255) DEFAULT NULL,
  `values` text NOT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `fk_user_setting_guardian` (`guardian_id`),
  KEY `idx_category_sub` (`category`,`sub_category`),
  CONSTRAINT `fk_user_setting_guardian` FOREIGN KEY (`guardian_id`) REFERENCES `guardians` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=157 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

