-- 테이블 health_care.vital_signs_archive_2011 구조 내보내기
CREATE TABLE IF NOT EXISTS `vital_signs_archive_2011` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `senior_id` int(11) NOT NULL,
  `measurement_time` datetime NOT NULL,
  `blood_pressure_high` int(11) DEFAULT NULL,
  `blood_pressure_low` int(11) DEFAULT NULL,
  `heart_rate` int(11) DEFAULT NULL,
  `blood_sugar` int(11) DEFAULT NULL,
  `body_temperature` decimal(4,2) DEFAULT NULL,
  `is_normal` tinyint(1) DEFAULT 1,
  `notes` text DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_senior_time` (`senior_id`,`measurement_time`),
  KEY `idx_measurement_time` (`measurement_time`),
  KEY `idx_senior_created` (`senior_id`,`created_at`),
  CONSTRAINT `vital_signs_archive_2011_ibfk_1` FOREIGN KEY (`senior_id`) REFERENCES `seniors` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='2011년 생체신호 아카이브';

