-- 프로시저 health_care.CreateVitalArchiveTable 구조 내보내기
DELIMITER //
CREATE PROCEDURE `CreateVitalArchiveTable`(IN archive_year INT)
BEGIN
    DECLARE table_name VARCHAR(50);
    DECLARE sql_stmt TEXT;
    
    SET table_name = CONCAT('vital_signs_archive_', archive_year);
    
    SET @sql_check = CONCAT('SELECT COUNT(*) INTO @table_exists FROM information_schema.tables 
                            WHERE table_schema = DATABASE() AND table_name = ''', table_name, '''');
    PREPARE stmt FROM @sql_check;
    EXECUTE stmt;
    DEALLOCATE PREPARE stmt;
    
    IF @table_exists = 0 THEN
        SET sql_stmt = CONCAT('CREATE TABLE ', table_name, ' LIKE vital_signs');
        
        PREPARE stmt FROM sql_stmt;
        EXECUTE stmt;
        DEALLOCATE PREPARE stmt;
        
        SELECT CONCAT('Archive table ', table_name, ' created successfully') AS result;
    ELSE
        SELECT CONCAT('Archive table ', table_name, ' already exists') AS result;
    END IF;
END//
DELIMITER ;

